"""
FunctionExtractor - Unified function extraction for anchor construction.

Consolidates function extraction logic from:
- summary_function_proto/get_ancor2envidence.py: process_operator_functions()
- sub_function/extract/extract_functions.py: extract_function_name(), find_function_body_start(),
  find_matching_brace(), extract_functions_from_file()
- sub_function/merge/merge_func_extract.py: convert_functions_to_anchor_tuple()

Uses common infrastructure:
- common/file_discovery.py: find_aclnn_cpp_files()
- common/data_loader.py: load_functions_json()
- common/brace_utils.py: find_function_body_start(), find_matching_brace()
- common/anchor_builder.py: build_function_anchor()
- common/id_generator.py: IdGenerator
"""

import logging
import re
from pathlib import Path
from typing import Any, Optional

from src.snapshot_construction.anchor_construction.common.anchor_builder import (
    build_function_anchor,
)
from src.snapshot_construction.anchor_construction.common.brace_utils import (
    find_function_body_start,
    find_matching_brace,
)
from src.snapshot_construction.anchor_construction.common.data_loader import DataLoader
from src.snapshot_construction.anchor_construction.common.file_discovery import (
    find_aclnn_cpp_files,
)
from src.snapshot_construction.anchor_construction.common.id_generator import (
    IdConfig,
    IdGenerator,
)
from src.snapshot_construction.anchor_construction.common.path_config import PathConfig

logger = logging.getLogger(__name__)


class FunctionExtractor:
    """Unified function extractor for anchor construction.

    Extracts aclnnStatus function signatures from C++ files, builds function anchors
    with call/callee/return information from DataLoader, and generates anchor/evidence IDs.

    Does NOT assign gene_rule - that is handled by downstream processors.
    """

    def __init__(
        self,
        path_config: PathConfig,
        data_loader: DataLoader,
        id_generator: IdGenerator,
    ):
        """Initialize FunctionExtractor.

        Args:
            path_config: PathConfig instance for operator paths
            data_loader: DataLoader instance for loading function data
            id_generator: IdGenerator instance for generating anchor/evidence IDs
        """
        self._path_config = path_config
        self._data_loader = data_loader
        self._id_generator = id_generator
        logger.debug("FunctionExtractor initialized")

    def extract(
        self,
        operator_path: Path,
        source_files: Optional[list[str]] = None,
    ) -> list[dict[str, Any]]:
        """Extract function anchors from operator directory.

        Args:
            operator_path: Path to operator source directory
            source_files: Optional list of source file paths/names to filter by.
                When provided, only files matching (by path string or basename) are kept.
                When None, all discovered files are returned (backward compatible).

        Returns:
            List of function anchor dicts WITHOUT gene_rule assigned.
            Each anchor has:
            - anchor_id: Generated by IdGenerator
            - anchor_information: type="function", level1/level2/level3
            - evidence: List with evidence_id and envidence_id
        """
        logger.info(f"Extracting functions from {operator_path}")

        # Discover aclnn_*.cpp files
        cpp_files = find_aclnn_cpp_files(operator_path)
        logger.debug(f"Found {len(cpp_files)} aclnn_*.cpp files")

        if source_files is not None:
            source_names = {Path(s).name for s in source_files}
            source_strs = set(source_files)
            cpp_files = [fp for fp in cpp_files if str(fp) in source_strs or fp.name in source_names]
            logger.debug(f"Filtered to {len(cpp_files)} cpp files matching source_files")

        # Load functions.json for call/callee/return data
        functions_json = self._data_loader.load_functions_json()

        # Build func_info_map: function_name -> {calls, called_by, returns}
        func_info_map = {}
        for func_item in functions_json:
            func_id = func_item.get("id", "")
            if func_id:
                func_info_map[func_id] = {
                    "calls": func_item.get("calls", []),
                    "called_by": func_item.get("called_by", []),
                    "returns": func_item.get("returns", []),
                }

        logger.debug(f"Built func_info_map with {len(func_info_map)} entries")

        # Extract functions from each file
        anchors = []

        for cpp_file in cpp_files:
            file_anchors = self._extract_functions_from_file(cpp_file, func_info_map)
            anchors.extend(file_anchors)

        logger.info(f"Extracted {len(anchors)} function anchors")
        return anchors

    def _extract_functions_from_file(
        self,
        file_path: Path,
        func_info_map: dict[str, dict[str, list[str]]],
    ) -> list[dict[str, Any]]:
        """Extract function anchors from a single C++ file.

        Args:
            file_path: Path to C++ file
            func_info_map: Map of function_name -> {calls, called_by, returns}

        Returns:
            List of function anchor dicts for this file
        """
        logger.debug(f"Processing file: {file_path}")

        # Read file content
        try:
            with open(file_path, "r", encoding="utf-8", errors="ignore") as f:
                content = f.read()
        except Exception as e:
            logger.warning(f"Failed to read file {file_path}: {e}")
            return []

        # Extract function signatures and bodies
        functions = self._extract_function_signatures(content)

        # Build anchors for each function
        anchors = []

        for func_name, func_sign in functions:
            # Get call/callee/return info
            func_info = func_info_map.get(func_name, {})
            calls = func_info.get("calls", [])
            called_by = func_info.get("called_by", [])
            returns = func_info.get("returns", [])

            # Generate anchor_id and evidence_id
            anchor_id, evidence_id = self._id_generator.next_pair("function")

            # Build relative path (from ops/ onwards)
            relative_path = self._get_relative_path(file_path)

            # Build function anchor WITHOUT gene_rule
            anchor = build_function_anchor(
                anchor_id=anchor_id,
                file_path=relative_path,
                function_name=func_name,
                function_sign=func_sign,
                calls=calls,
                called_by=called_by,
                returns=returns,
                gene_deter="",  # Empty - assigned by downstream
                gene_target=[],  # Empty - assigned by downstream
                evidence_id=evidence_id,
                note="以下为function型标准结构",
            )

            # Add envidence_id (legacy compatibility)
            anchor["evidence"][0]["envidence_id"] = evidence_id

            anchors.append(anchor)
            logger.debug(f"Built anchor for function: {func_name}")

        return anchors

    def _extract_function_signatures(self, content: str) -> list[tuple[str, str]]:
        """Extract function signatures from C++ content.

        Uses regex pattern: aclnnStatus\\s+(aclnn\\w+)

        Args:
            content: C++ file content

        Returns:
            List of tuples (function_name, full_signature)
        """
        functions = []
        lines = content.split("\n")

        i = 0
        while i < len(lines):
            line = lines[i]

            # Match aclnnStatus function signature
            func_name = self._extract_function_name(line)
            if func_name:
                # Find function body start (opening brace)
                line_start_pos = content.find(line)
                body_start_pos = find_function_body_start(content, line_start_pos)

                if body_start_pos == -1:
                    logger.warning(f"No function body found for {func_name}")
                    i += 1
                    continue

                # Find matching closing brace
                body_end_pos = find_matching_brace(content, body_start_pos)

                if body_end_pos == -1:
                    logger.warning(f"No matching brace for {func_name}")
                    i += 1
                    continue

                # Extract full function (signature + body)
                end = body_end_pos + 1
                full_function = content[line_start_pos:end]

                functions.append((func_name, full_function))

                # Skip to end of function body
                line_count_before_body = content[: body_end_pos + 1].count("\n")
                i = line_count_before_body
                continue

            i += 1

        return functions

    def _extract_function_name(self, line: str) -> str | None:
        """Extract function name from a line containing aclnnStatus signature.

        Args:
            line: Line to search

        Returns:
            Function name if found, None otherwise
        """
        pattern = r"(aclnnStatus\s+)(aclnn\w+)"
        match = re.search(pattern, line)
        if match:
            return match.group(2)
        return None

    def _get_relative_path(self, file_path: Path) -> str:
        """Get relative path from ops/ onwards.

        Args:
            file_path: Absolute file path

        Returns:
            Relative path string (e.g., "ops/math/abs/aclnn_abs.cpp")
        """
        parts = file_path.parts
        try:
            ops_idx = parts.index("ops")
            relative_parts = parts[ops_idx:]
            return str(Path(*relative_parts))
        except ValueError:
            # "ops" not in path, return as-is
            return str(file_path)


if __name__ == "__main__":
    # Self-test
    import os

    print("Testing FunctionExtractor...")

    from src.snapshot_construction.anchor_construction.common.data_loader import (
        DataLoader,
    )
    from src.snapshot_construction.anchor_construction.common.id_generator import (
        IdConfig,
        IdGenerator,
    )
    from src.snapshot_construction.anchor_construction.common.path_config import (
        PathConfig,
    )

    # Create test config
    operator_path = Path(
        os.environ.get(
            "TEST_OPERATOR_PATH",
            Path(os.environ.get("CANN_OPS_ROOT", "")) / "math" / "abs",
        )
    )
    if not operator_path.exists():
        raise SystemExit(
            f"operator_path not found: {operator_path}\n"
            "请设置 TEST_OPERATOR_PATH 或 CANN_OPS_ROOT 环境变量指向本机 ops 检出"
        )
    out_path = Path("/tmp/anchor_test_output")
    path_config = PathConfig(operator_path, out_path)

    data_loader = DataLoader(path_config)

    id_config = IdConfig(
        type_prefix_in_anchor=True,
        type_prefix_in_evidence=True,
        shared_counters=True,
    )
    id_generator = IdGenerator(id_config)

    # Create extractor
    extractor = FunctionExtractor(path_config, data_loader, id_generator)

    # Extract functions
    anchors = extractor.extract(operator_path)

    print(f"Extracted {len(anchors)} function anchors")

    if anchors:
        print("\nFirst anchor:")
        anchor = anchors[0]
        print(f"  anchor_id: {anchor['anchor_id']}")
        print(f"  type: {anchor['anchor_information']['type']}")
        print(f"  function_name: {anchor['anchor_information']['level1']['function_name']}")
        print(f"  evidence_id: {anchor['evidence'][0].get('evidence_id')}")
        print(f"  envidence_id: {anchor['evidence'][0].get('envidence_id')}")

    print("\nOK")
